package registry

// The collision shapes of the block families no Go code models, kept as the
// vanilla server gave them: one box list per state of the beds, the cakes,
// the anvils, the cauldrons, the hoppers, the bells, the pots and the
// pitcher crop, generated by tools/gen blockshapes. The entity sweep reads
// this table for the families it names; a family that gains a Go model of
// its own comes off the generator and reads that instead.

// blockShapes holds each state's shape index into blockShapeBoxes, one
// based, zero for a state the table does not carry.
var blockShapes = func() []uint16 {
	shapes := make([]uint16, len(stateByID))
	for _, e := range blockShapeEntries {
		shapes[e.state] = e.shape + 1
	}
	return shapes
}()

// BlockShapeBoxes gives a block state's collision boxes in 32nds of a
// block, as the vanilla server's own getCollisionShape read them, and false
// when the state's family is not one the generated table carries. The
// caller keeps the empty shape to the collision-top table.
func BlockShapeBoxes(state uint16) ([][6]int8, bool) {
	if int(state) >= len(blockShapes) {
		return nil, false
	}
	shape := blockShapes[state]
	if shape == 0 {
		return nil, false
	}
	return blockShapeBoxes[shape-1], true
}
